for rec in capacity_records:
    vid = int(rec['values']['VehicleID'])
    vehicle_ids.append(vid)
    vehicle_types[vid] = rec['values']['VehicleType']
    per_type_capacity[vid] = int(rec['values']['Capacity'])
vehicle_ids.sort()
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
benefit_by_type = {}
for rec in product_records:
    benefit_by_type[rec['values']['ProductName']] = int(rec['values']['Value'])
benefit_coeff = {}
for vid in vehicle_ids:
    vtype = vehicle_types[vid]
    if vtype not in benefit_by_type:
        raise ValueError(f"Missing benefit coefficient for vehicle type '{vtype}'")
    benefit_coeff[vid] = benefit_by_type[vtype]
total_capacity = sum((per_type_capacity[vid] for vid in vehicle_ids))
m = gp.Model('NewCarSalesInNorway1')
x_vars = m.addVars(vehicle_ids, lb=0, ub=[per_type_capacity[vid] for vid in vehicle_ids], vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((benefit_coeff[vid] * x_vars[vid] for vid in vehicle_ids)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((x_vars[vid] for vid in vehicle_ids)) <= total_capacity, name='total_capacity')
for vid in vehicle_ids:
    m.addConstr(x_vars[vid] <= per_type_capacity[vid], name=f'cap_{vid}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
